{
  "name": "DDS信号源",
  "name_en": "DDS signal generator",
  "manufacturer": "",
  "description": "基于直接数字合成的可编程信号源，可按实验时序设置输出的频率、幅度和相位，并可通过数字门控实现开关和脉冲输出。常用于原子物理、量子光学和精密测量实验中的AOM/EOM驱动、本振提供和相干控制。",
  "description_en": "A direct-digital-synthesis signal source with programmable frequency, amplitude, and phase, often with digital gating for on/off control and timed pulses. It is commonly used in atomic physics, quantum optics, and precision measurement experiments for AOM/EOM driving, local oscillator generation, and coherent control.",
  "tag_hints": [
    "direct digital synthesis",
    "RF signal generation",
    "programmable frequency amplitude phase",
    "gated pulse output",
    "AOM/EOM drive",
    "timed experiment sequencing"
  ],
  "actions": [
    {
      "action_name": "auto-disable",
      "description": "关闭DDS输出门控。",
      "description_en": "Disable the DDS output gate."
    },
    {
      "action_name": "auto-enable",
      "description": "开启DDS输出门控。",
      "description_en": "Enable the DDS output gate."
    },
    {
      "action_name": "auto-pulse",
      "description": "输出一次具有设定频率、幅度和相位的定时脉冲。",
      "description_en": "Generate a timed pulse with defined frequency, amplitude, and phase."
    },
    {
      "action_name": "auto-setamp",
      "description": "设置输出幅度。",
      "description_en": "Set the output amplitude."
    },
    {
      "action_name": "auto-setfreq",
      "description": "设置输出频率。",
      "description_en": "Set the output frequency."
    },
    {
      "action_name": "auto-setphase",
      "description": "设置输出相位。",
      "description_en": "Set the output phase."
    },
    {
      "action_name": "auto-clock_limit",
      "description": "查看时序更新的最高时钟速率限制。",
      "description_en": "View the maximum clock rate limit for timed updates."
    },
    {
      "action_name": "auto-trigger_delay",
      "description": "查看触发到输出生效之间的延迟。",
      "description_en": "View the delay between a trigger and the output response."
    },
    {
      "action_name": "auto-wait_delay",
      "description": "查看等待或继续运行相关的附加延迟。",
      "description_en": "View the additional delay associated with wait or resume timing."
    },
    {
      "action_name": "auto-get_all_outputs",
      "description": "列出该DDS关联的全部输出量，如频率、幅度、相位和门控。",
      "description_en": "List all outputs associated with the DDS, such as frequency, amplitude, phase, and gate."
    },
    {
      "action_name": "auto-apply_calibration",
      "description": "对输出量应用校准换算。",
      "description_en": "Apply calibration conversion to an output parameter."
    },
    {
      "action_name": "auto-instruction_to_string",
      "description": "将已编程的输出指令转换为可读文本。",
      "description_en": "Convert a programmed output instruction into readable text."
    },
    {
      "action_name": "auto-add_instruction",
      "description": "向实验时序中添加一条DDS输出指令。",
      "description_en": "Add a DDS output instruction to the experiment timing sequence."
    },
    {
      "action_name": "auto-do_checks",
      "description": "检查已编程输出是否存在冲突或超出限制。",
      "description_en": "Check the programmed output for conflicts or limit violations."
    },
    {
      "action_name": "auto-offset_instructions_from_trigger",
      "description": "按触发偏移整体平移已编程指令时间。",
      "description_en": "Offset all programmed instruction times relative to a trigger."
    },
    {
      "action_name": "auto-get_change_times",
      "description": "获取输出参数发生变化的时间点。",
      "description_en": "Get the times at which output parameters change."
    },
    {
      "action_name": "auto-get_ramp_times",
      "description": "获取斜坡扫描的时间区间。",
      "description_en": "Get the time intervals of ramped segments."
    },
    {
      "action_name": "auto-make_timeseries",
      "description": "生成用于执行的输出时间序列。",
      "description_en": "Generate the output time series for execution."
    },
    {
      "action_name": "auto-expand_timeseries",
      "description": "将输出时间序列展开为逐点序列。",
      "description_en": "Expand the output time series into point-by-point values."
    },
    {
      "action_name": "auto-ramp",
      "description": "对DDS控制参数执行斜坡扫描，如频率、幅度或相位。",
      "description_en": "Apply a ramp to a DDS control parameter such as frequency, amplitude, or phase."
    },
    {
      "action_name": "auto-sine",
      "description": "对DDS控制参数施加正弦调制。",
      "description_en": "Apply sinusoidal modulation to a DDS control parameter."
    },
    {
      "action_name": "auto-sine_ramp",
      "description": "对DDS控制参数执行正弦形斜坡扫描。",
      "description_en": "Apply a sinusoidal ramp to a DDS control parameter."
    },
    {
      "action_name": "auto-sine4_ramp",
      "description": "对DDS控制参数执行四次正弦形平滑斜坡。",
      "description_en": "Apply a sine-to-the-fourth smooth ramp to a DDS control parameter."
    },
    {
      "action_name": "auto-sine4_reverse_ramp",
      "description": "对DDS控制参数执行反向四次正弦形平滑斜坡。",
      "description_en": "Apply a reverse sine-to-the-fourth smooth ramp to a DDS control parameter."
    },
    {
      "action_name": "auto-exp_ramp",
      "description": "对DDS控制参数执行指数斜坡扫描。",
      "description_en": "Apply an exponential ramp to a DDS control parameter."
    },
    {
      "action_name": "auto-exp_ramp_t",
      "description": "按时间参数定义DDS控制参数的指数斜坡。",
      "description_en": "Apply an exponential ramp to a DDS control parameter using time-based parameters."
    },
    {
      "action_name": "auto-piecewise_accel_ramp",
      "description": "对DDS控制参数执行分段加速度受控斜坡。",
      "description_en": "Apply a piecewise acceleration-controlled ramp to a DDS control parameter."
    },
    {
      "action_name": "auto-square_wave",
      "description": "对DDS控制参数施加方波调制。",
      "description_en": "Apply square-wave modulation to a DDS control parameter."
    },
    {
      "action_name": "auto-square_wave_levels",
      "description": "对DDS控制参数施加指定高低电平的方波调制。",
      "description_en": "Apply square-wave modulation with defined high and low levels to a DDS control parameter."
    },
    {
      "action_name": "auto-customramp",
      "description": "按自定义函数对DDS控制参数进行扫描。",
      "description_en": "Apply a custom-defined ramp to a DDS control parameter."
    },
    {
      "action_name": "auto-constant",
      "description": "将DDS控制参数保持为常值。",
      "description_en": "Hold a DDS control parameter at a constant value."
    },
    {
      "action_name": "auto-static_value",
      "description": "设置静态输出值。",
      "description_en": "Set a static output value."
    },
    {
      "action_name": "auto-go_high",
      "description": "将数字门控置为高电平。",
      "description_en": "Drive the digital gate high."
    },
    {
      "action_name": "auto-go_low",
      "description": "将数字门控置为低电平。",
      "description_en": "Drive the digital gate low."
    },
    {
      "action_name": "auto-repeat_pulse_sequence",
      "description": "重复输出预定义的脉冲序列。",
      "description_en": "Repeat a predefined pulse sequence."
    },
    {
      "action_name": "auto-generate_code",
      "description": "生成设备执行所需的时序配置数据。",
      "description_en": "Generate the timing configuration data required for device execution."
    },
    {
      "action_name": "auto-trigger",
      "description": "发出触发脉冲或安排触发事件。",
      "description_en": "Issue a trigger pulse or schedule a trigger event."
    },
    {
      "action_name": "auto-add_device",
      "description": "添加关联的子通道或从属输出。",
      "description_en": "Add an associated child channel or subordinate output."
    }
  ]
}

